# The copropriete, the parcel with the largest building
COPROPRIETE = "1320290000A0107"


def fetch(sql: str) -> list:
    # Do not keep the connection object, it is invalidated when connections are reloaded
    metadata = QgsProviderRegistry.instance().providerMetadata("postgres")
    return metadata.findConnection("test_database").executeSql(sql)


@pytest.fixture(scope="module")
def database(fixtures: Path) -> CadastreDatabase:
    remove_schema()
    metadata = QgsProviderRegistry.instance().providerMetadata("postgres")
    metadata.findConnection("test_database").createSchema(TEST_SCHEMA)
    assert cadastreImport(import_options(CornillonMajic, fixtures), CadastreFeedback()).run()
    return CadastreDatabase.from_connection("postgis", "test_database", TEST_SCHEMA)


@pytest.fixture(scope="module")
def parcelles(database: CadastreDatabase) -> Iterator[QgsVectorLayer]:
    """ The parcelle_info layer, used by the fiche parcellaire and the export """
    project = QgsProject.instance()
    project.clear()
    CadastreLoading(CadastreFeedback()).process_loading(LoadingOptions(database, main_layers_only=True))
    yield project.mapLayersByName("Parcelles")[0]
    project.clear()


def feature(layer: QgsVectorLayer, geo_parcelle: str) -> QgsFeature:
    request = QgsFeatureRequest().setFilterExpression(f"\"geo_parcelle\" = '{geo_parcelle}'")
    return next(layer.getFeatures(request))


