@pytest.mark.parametrize(
    "sql",
    [
        # EDIGEO <-> MAJIC
        "SELECT count(*) FROM cadastre.parcelle p "
        "LEFT JOIN cadastre.geo_parcelle g ON g.geo_parcelle = p.parcelle WHERE g.geo_parcelle IS NULL",
        "SELECT count(*) FROM cadastre.geo_parcelle g "
        "LEFT JOIN cadastre.parcelle p ON g.geo_parcelle = p.parcelle WHERE p.parcelle IS NULL",
        # Parcels and owners
        "SELECT count(*) FROM cadastre.parcelle p "
        "LEFT JOIN cadastre.proprietaire pr ON pr.comptecommunal = p.comptecommunal WHERE pr.proprietaire IS NULL",
        "SELECT count(*) FROM cadastre.suf s "
        "LEFT JOIN cadastre.parcelle p ON p.parcelle = s.parcelle WHERE p.parcelle IS NULL",
        # Buildings
        "SELECT count(*) FROM cadastre.local10 l "
        "LEFT JOIN cadastre.parcelle p ON p.parcelle = l.parcelle WHERE p.parcelle IS NULL",
        "SELECT count(*) FROM cadastre.local10 l "
        "LEFT JOIN cadastre.comptecommunal c ON c.comptecommunal = l.comptecommunal WHERE c.comptecommunal IS NULL",
        "SELECT count(*) FROM cadastre.local10 l "
        "LEFT JOIN cadastre.pev p ON p.local10 = l.local10 WHERE p.pev IS NULL",
        "SELECT count(*) FROM cadastre.pev p "
        "LEFT JOIN cadastre.pevtaxation t ON t.pev = p.pev WHERE t.pev IS NULL",
        # Copropriete
        "SELECT count(*) FROM cadastre.lotslocaux ll "
        "LEFT JOIN cadastre.local10 l ON l.local10 = ll.local10 WHERE l.local10 IS NULL",
        "SELECT count(*) FROM cadastre.lots l "
        "LEFT JOIN cadastre.comptecommunal c ON c.comptecommunal = l.comptecommunal WHERE c.comptecommunal IS NULL",
        # Addresses and TOPO
        "SELECT count(*) FROM cadastre.parcelle p LEFT JOIN cadastre.voie v "
        "ON SUBSTR(p.voie, 1, 6) || SUBSTR(p.voie, 12, 4) = SUBSTR(v.voie, 1, 6) || SUBSTR(v.voie, 12, 4) "
        "WHERE v.voie IS NULL",
    ],
    ids=[
        "parcelle-geo_parcelle", "geo_parcelle-parcelle", "parcelle-proprietaire", "suf-parcelle",
        "local-parcelle", "local-compte", "local-pev", "pev-taxation", "lot-local", "lot-compte", "parcelle-voie",
    ],
)
def test_links(database: CadastreDatabase, sql: str):
    """ Every row has its related row """
    assert fetch(sql) == [[0]]


